function cloudBanking(page){
 const topics=[
 ["AWS IAM và Amazon S3","https://docs.aws.amazon.com/AmazonS3/latest/userguide/GetStartedWithS3.html","Bucket chứa object. Dùng IAM role với quyền tối thiểu, chặn truy cập công khai và kiểm tra mã hóa khi lưu.","Tạo thư mục raw và curated trên máy. Đặt CSV đầu vào vào raw, lưu bản đã kiểm trùng trong curated và ghi số dòng theo ngày.","Tệp raw giữ nguyên và curated chỉ chứa mã giao dịch duy nhất.","Vì sao tách quyền đọc raw và ghi curated?","Giảm phạm vi ảnh hưởng khi luồng xử lý lỗi hoặc dùng sai quyền."],
 ["Amazon Redshift","https://docs.aws.amazon.com/redshift/latest/dg/t_loading-tables-from-s3.html","COPY nạp dữ liệu S3 theo lô. Nạp vào staging, đối soát rồi ghi fact theo grain một giao dịch.","Dùng lab Mapping nhóm giao dịch. Đếm dòng và tổng tiền theo ngày, tiền tệ. Phác thảo staging và bảng fact có khóa giao dịch.","Có bảng kiểm theo ngày và đơn vị tiền tệ; không gộp các đồng tiền khi chưa quy đổi.","COUNT khớp có đủ để công bố KPI?","Cần kiểm khóa duy nhất, tiền tệ và tổng tiền trong cùng phạm vi."],
 ["Amazon QuickSight","https://docs.aws.amazon.com/quick/latest/userguide/enabling-access-redshift.html","Dataset xác định trường cho dashboard. Phân quyền theo hàng giới hạn dữ liệu người xem được đọc.","Dùng Excel hoặc Power BI dựng bảng tổng tiền theo ngày và tiền tệ, thêm bộ lọc chi nhánh. Lập hai tài khoản giả định và ma trận dòng được xem.","Hai người xem có cùng định nghĩa KPI nhưng thấy phạm vi chi nhánh khác nhau.","Ẩn cột chi nhánh trên biểu đồ có giới hạn quyền không?","Không. Quyền phải được kiểm soát ở dataset hoặc lớp truy cập phù hợp."],
 ["Amazon SageMaker AI","https://docs.aws.amazon.com/sagemaker/latest/dg/whatis.html","Huấn luyện trên dữ liệu giả lập. Chia tập theo thời gian và loại biến chỉ xuất hiện sau kết quả cần dự báo.","Lập baseline bằng Python cục bộ trên mẫu khoản vay giả lập. Chia tập trước và sau một mốc thời gian, dùng biến có sẵn ở ngày đánh giá và báo precision, recall.","Có bảng nhầm lẫn và danh sách trường đã loại vì rò rỉ nhãn.","Có dùng trạng thái trả nợ xác nhận sau ngày quyết định không?","Không. Biến đó chưa có ở thời điểm suy luận và sẽ làm điểm đánh giá lạc quan."],
 ["Apache Unomi CDP","https://unomi.apache.org/documentation.html","Profile mô tả người dùng; event mô tả hành động theo thời gian. Consent quyết định mục đích sử dụng được phép.","Tạo CSV giả lập gồm profile_id, event_type, event_time và consent. Gắn nhóm khách thử tính năng trong 7 ngày và có đồng ý tiếp thị.","Danh sách có căn cứ cho từng điều kiện và loại người rút sự đồng ý.","Hai thiết bị cùng email có tự động thành một profile không?","Phải có quy tắc định danh và xử lý xung đột rõ ràng trước khi ghép."],
 ["Mambu và Core Banking số","https://docs.mambu.com/api/pages/api-v2/welcome/","Tách khách hàng, tài khoản, giao dịch và lịch trả nợ. Lưu mã giao dịch nguồn để đối chiếu sổ cái.","Lấy nhóm tài khoản và GL từ kho Mapping. Mô phỏng một khoản giải ngân, một lần trả nợ và một giao dịch đảo. Đối chiếu số dòng, mã giao dịch và tổng Nợ/Có.","Có bảng ngoại lệ phân biệt bút toán thiếu, giao dịch đảo và lỗi khác ngày nghiệp vụ.","Vì sao cần khóa chống ghi trùng khi retry API?","Retry có thể lặp thao tác sau khi hệ thống đã ghi thành công nhưng chưa trả phản hồi."]
 ];
 return page("Học theo JD","AWS & Ngân hàng số","Sáu bài tiếng Việt với bài thực hành mô phỏng. Có thể học trên máy cá nhân mà không tạo tài nguyên cloud.")+
 '<div class="de-grid">'+topics.map(([t,u,r,l,e,q,a])=>`<article class="de-card"><h2>${t}</h2><p>${r}</p><h3>Thực hành</h3><p>${l}</p><p><strong>Kết quả cần có</strong> ${e}</p><details><summary>${q}</summary><p>${a}</p></details><p><a href="${u}" target="_blank" rel="noopener noreferrer">Tài liệu chính thức</a></p></article>`).join("")+
 '</div><section class="content"><h2>Dự án tổng hợp</h2><p>Mô phỏng Core Banking và Unomi phát sinh dữ liệu giả lập. Tách raw và curated như S3, nạp staging vào SQLite thay Redshift, rồi dựng dashboard như QuickSight. Nộp sơ đồ luồng, quy tắc consent, SQL kiểm soát và ảnh dashboard. Phần SageMaker là bài mô hình riêng.</p><p><a href="#mapping">Mở dữ liệu và lab SQLite</a> · <a href="https://aws.amazon.com/s3/getting-started/" target="_blank" rel="noopener noreferrer">Học liệu AWS S3</a></p></section>';
}
